// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

var N_FRAMES = 100;
var eps = 0.01;

var r = 80;
var h = r*Math.sqrt(3)/2;

var delta = 1 - Math.sqrt(3)/2;

function setup() {
  createCanvas(7*r, 9*r*sqrt(3)/2);
  noStroke();
}

function draw() {
  background("#fffbe6");

  let t0 = map((frameCount%N_FRAMES)/N_FRAMES, 0, 1, 
           (sqrt(32*sq(delta) + 1) + 4*delta - 1)/(8*delta), 
           (-sqrt(32*sq(delta) + 1) + 4*delta + 1)/(8*delta));

  let a = "#62b6de", b = "#f9d531", c = "#2b67af", d = "#abcd5e";

  translate(width/2, height/2);

  makeLine(t0, 0, [c, b]);
  makeLine(1-t0, TAU/6, [b, a]);
  makeLine(t0, 2*TAU/6, [a, d]);
  makeLine(1-t0, 3*TAU/6, [d, b]);
  makeLine(t0, 4*TAU/6, [b, a]);
  makeLine(1-t0, 5*TAU/6, [a, c]);

  push();
  translate(r*3/2, h);
  makeLine(t0, 0, [a, c]);
  makeLine(1-t0, TAU/6, [c, d]);
  makeLine(t0, 2*TAU/6, [d, b]);
  makeLine(t0, 4*TAU/6, [c, d]);
  makeLine(1-t0, 5*TAU/6, [d, a]);
  pop();

  push();
  translate(0, 2*h);
  makeLine(t0, 0, [d, a]);
  makeLine(1-t0, TAU/6, [a, b]);
  makeLine(t0, 2*TAU/6, [b, c]);
  makeLine(1-t0, 3*TAU/6, [c, a]);
  pop();

  push();
  translate(-r*3/2, h);
  makeLine(1-t0, TAU/6, [c, d]);
  makeLine(t0, 2*TAU/6, [d, b]);
  makeLine(1-t0, 3*TAU/6, [b, c]);
  makeLine(t0, 4*TAU/6, [c, d]);
  pop();

  push();
  translate(-r*3/2, -h);
  makeLine(t0, 2*TAU/6, [c, a]);
  makeLine(1-t0, 3*TAU/6, [a, d]);
  makeLine(t0, 4*TAU/6, [d, c]);
  makeLine(1-t0, 5*TAU/6, [c, b]);
  pop();

  push();
  translate(0, -2*h);
  makeLine(t0, 0, [d, a]);
  makeLine(1-t0, 3*TAU/6, [c, a]);
  makeLine(t0, 4*TAU/6, [a, b]);
  makeLine(1-t0, 5*TAU/6, [b, d]);
  pop();

  push();
  translate(r*3/2, -h);
  makeLine(t0, 0, [b, d]);
  makeLine(t0, 4*TAU/6, [d, c]);
  makeLine(1-t0, 5*TAU/6, [c, b]);
  pop();
}

function makeLine(t0, theta, colors) {
  fill(5);
  arc(0, 0, 2*r, 2*r, theta, theta+TAU/6, OPEN);
  arc(2*h*cos(theta+TAU/12), 2*h*sin(theta+TAU/12), 2*r, 2*r, theta+PI, theta+PI+TAU/6, OPEN);

  let t = t0;
  let idx = 0;
  let _wG_1 = 0; while ((t < 1-eps) && ++_wG_1 < 20000) {
    // draw circle
    let [x, y] = lerpPoints(r*cos(theta), r*sin(theta), r*cos(theta+TAU/6), r*sin(theta+TAU/6), t);
    fill(colors[idx%colors.length]);
    idx++;
    circle(x, y, delta*(1-sq(2*(t)-1))*2*r);

    // compute new t
    var a = t + delta*(1-sq(2*t-1));
    let t1 = (sqrt(16*a*delta + 16*sq(delta) - 8*delta + 1) + 4*delta-1)/(8*delta);
    t = t1;
  }

  t = t0;
  idx = 0;
  let _wG_2 = 0; while ((t > eps) && ++_wG_2 < 20000) {
    // compute new t
    var a = t - delta*(1-sq(2*t-1));
    let t2 = (-sqrt(-16*a*delta + 16*sq(delta) + 8*delta + 1) + 4*delta+1)/(8*delta);
    t = t2;

    // draw circle
    let [x, y] = lerpPoints(r*cos(theta), r*sin(theta), r*cos(theta+TAU/6), r*sin(theta+TAU/6), t);
    idx++;
    fill(colors[idx%colors.length]);
    circle(x, y, delta*(1-sq(2*(t)-1))*2*r);
  }
}

function lerpPoints(x1, y1, x2, y2, t) {
  let x3 = (1-t)*x1 + t*x2;
  let y3 = (1-t)*y1 + t*y2;
  return [x3, y3];
}
